import React from "react";
import "../theme.css";

function StatCard({ icon, label, value, hint, accent = "var(--primary)" }) {
  return (
    <div
      style={{
        background: "var(--surface)",
        border: "1px solid var(--border)",
        borderRadius: "18px",
        padding: "18px",
        boxShadow: "var(--shadow-sm)"
      }}
    >
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          gap: "12px"
        }}
      >
        <div
          style={{
            width: "46px",
            height: "46px",
            borderRadius: "14px",
            background: "rgba(124,58,237,0.10)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            color: accent,
            fontSize: "20px"
          }}
        >
          {icon}
        </div>
      </div>

      <div style={{ marginTop: "14px", color: "var(--muted)", fontSize: "14px" }}>
        {label}
      </div>

      <div
        style={{
          marginTop: "6px",
          fontSize: "30px",
          fontWeight: "800",
          color: "var(--text)"
        }}
      >
        {value}
      </div>

      {hint ? (
        <div style={{ marginTop: "8px", color: "var(--muted)", fontSize: "13px" }}>
          {hint}
        </div>
      ) : null}
    </div>
  );
}

export default StatCard;
